21	// partIsoStore 构造初始库存 12 件的已登记备件：可选登记一个保修 60 天的
22	// 产品和若干保修资格请求，用于随后预留两笔不同请求的承诺。
23	func partIsoStore(t *testing.T, requests ...string) *Store {
24		t.Helper()
25		s := NewStore()
26		if err := s.RegisterPart(partIsolationPartID, 12); err != nil {
27			t.Fatalf("register part: %v", err)
28		}
29		if len(requests) == 0 {
30			return s
31		}
32		if err := s.RegisterProduct("p-iso", t0, 60, nil); err != nil {
33			t.Fatalf("register product: %v", err)
34		}
35		for _, id := range requests {
36			if err := s.SubmitRequest(id, "p-iso", "FAULTY"); err != nil {
37				t.Fatalf("submit request %s: %v", id, err)
38			}
39		}
40		return s
41	}
42	
43	// partIsoExpiry 给出一个晚于全部操作时刻的到期时刻，各承诺可给不同时刻以
44	// 回归保障修改取回结果不会篡改其他承诺的到期时刻。
45	func partIsoExpiry(n int) time.Time {
46		return t0.Add(time.Duration(n) * day)
47	}
48	
49	// assertPartIsoAccount 断言某次 PartStatus 的库存三项为期望值。
50	func assertPartIsoAccount(t *testing.T, st *PartStatus, physical, occupied, committable int) {
51		t.Helper()
52		if st.PhysicalRemaining != physical || st.ActiveOccupied != occupied || st.Committable != committable {
53			t.Fatalf("stock account phys=%d occupied=%d committable=%d, want phys=%d occupied=%d committable=%d",
54				st.PhysicalRemaining, st.ActiveOccupied, st.Committable, physical, occupied, committable)
55		}
56	}
57	
58	// assertDetailFact 断言一条明细完整反映一笔承诺的查询当时事实：归属、原定、
59	// 已用、未用、状态与到期时刻。
60	func assertDetailFact(t *testing.T, d CommitmentDetail, requestID string, original, used, remaining int, status CommitmentStatus, expiry time.Time) {
61		t.Helper()
62		if d.RequestID != requestID || d.PartID != partIsolationPartID ||
63			d.OriginalQuantity != original || d.UsedQuantity != used || d.RemainingQuantity != remaining ||
64			d.Status != status || !d.Expiry.Equal(expiry) {
65			t.Fatalf("detail %q: req=%s part=%s orig=%d used=%d rem=%d status=%s expiry=%v; "+
66				"want req=%s orig=%d used=%d rem=%d status=%s expiry=%v",
67				d.CommitmentID, d.RequestID, d.PartID, d.OriginalQuantity, d.UsedQuantity, d.RemainingQuantity, d.Status, d.Expiry,
68				requestID, original, used, remaining, status, expiry)
69		}
70	}
71	
72	// TestPartStatusResultsAreIndependentAcrossQueries 同一备件被不同请求占用：
73	// 初始库存 12，两笔承诺分别预留 5（已使用 2）和 4，查询时两笔都未到期、
74	// 未取消。调用方取得两份结果后任意修改其中一份，另一份、重新查询的结果
75	// 以及仓库保存的承诺归属与已用数量都继续反映原有事实。
76	func TestPartStatusResultsAreIndependentAcrossQueries(t *testing.T) {
77		s := partIsoStore(t, "req-five", "req-four")
78	
79		expFive := partIsoExpiry(40)
80		expFour := partIsoExpiry(30)
81		if _, err := s.Reserve("c-five", "req-five", partIsolationPartID, 5, expFive, nowOK); err != nil {
82			t.Fatalf("reserve c-five: %v", err)
83		}
84		if _, err := s.Reserve("c-four", "req-four", partIsolationPartID, 4, expFour, nowOK); err != nil {
85			t.Fatalf("reserve c-four: %v", err)
86		}
87		// 五件那笔已使用两件：实物剩余 10，有效占用 7（3+4），可承诺 3。
88		if _, err := s.Use("u-five-2", "c-five", 2, nowOK); err != nil {
89			t.Fatalf("use 2 from c-five: %v", err)
90		}
91	
92		first, err := s.PartStatus(partIsolationPartID, nowOK)
93		if err != nil {
94			t.Fatalf("first part status: %v", err)
95		}
96		assertPartIsoAccount(t, first, 10, 7, 3)
97		if len(first.Details) != 2 {
98			t.Fatalf("first details = %d, want 2", len(first.Details))
99		}
100		assertDetailFact(t, mustDetailByID(t, first.Details, "c-five"), "req-five", 5, 2, 3, CommitmentActive, expFive)
101		assertDetailFact(t, mustDetailByID(t, first.Details, "c-four"), "req-four", 4, 0, 4, CommitmentActive, expFour)
102		// 明细按承诺编号排序。
103		if first.Details[0].CommitmentID != "c-five" || first.Details[1].CommitmentID != "c-four" {
104			t.Fatalf("details order = %s, %s, want c-five, c-four", first.Details[0].CommitmentID, first.Details[1].CommitmentID)
105		}
106	
107		// 第二份结果随后取得，两者内容相同但必须是各自独立的结果。
108		second, err := s.PartStatus(partIsolationPartID, nowOK)
109		if err != nil {
110			t.Fatalf("second part status: %v", err)
111		}
112		assertPartIsoAccount(t, second, 10, 7, 3)
113		if len(second.Details) != 2 {
114			t.Fatalf("second details = %d, want 2", len(second.Details))
115		}
116	
117		// 调用方为了展示而修改第二份结果：改动库存数字、承诺数量与状态，并
118		// 替换、删除、补入明细。这些修改只能影响第二份结果本身。
119		second.PhysicalRemaining = 100
120		second.ActiveOccupied = 90
121		second.Committable = 10
122		second.PartID = "rewritten-part"
123		for i := range second.Details {
124			d := &second.Details[i]
125			d.OriginalQuantity += 50
126			d.UsedQuantity += 40
127			d.RemainingQuantity += 10
128			d.RequestID = "rewritten-" + d.CommitmentID
129			d.Status = CommitmentCanceled
130		}
131		// 替换整条 c-five 明细、删除 c-four 明细、补入一条虚构明细。
132		second.Details[0] = CommitmentDetail{
133			CommitmentID:      "c-five",
134			RequestID:         "req-display",
135			PartID:            "rewritten-part",
136			OriginalQuantity:  77,
137			UsedQuantity:      77,
138			RemainingQuantity: 0,
139			Expiry:            partIsoExpiry(99),
140			Status:            CommitmentExpired,
141		}
142		second.Details = append(second.Details[:1], CommitmentDetail{
143			CommitmentID:      "c-fabricated",
144			RequestID:         "req-display",
145			PartID:            "rewritten-part",
146			OriginalQuantity:  6,
147			UsedQuantity:      0,
148			RemainingQuantity: 6,
149			Expiry:            partIsoExpiry(99),
150			Status:            CommitmentActive,
151		})
152	
153		// 先前取得的第一份结果保留查询当时的内容。
154		assertPartIsoAccount(t, first, 10, 7, 3)
155		if first.PartID != partIsolationPartID {
156			t.Fatalf("first result part id changed to %q", first.PartID)
157		}
158		if len(first.Details) != 2 {
159			t.Fatalf("first details = %d after mutating second result, want 2", len(first.Details))
160		}
161		assertDetailFact(t, mustDetailByID(t, first.Details, "c-five"), "req-five", 5, 2, 3, CommitmentActive, expFive)
162		assertDetailFact(t, mustDetailByID(t, first.Details, "c-four"), "req-four", 4, 0, 4, CommitmentActive, expFour)
163		if _, ok := detailByID(first, "c-fabricated"); ok {
164			t.Fatalf("first result gained fabricated detail")
165		}
