167		// 重新查询继续反映仓库的真实记录：10/7/3，两条 active 明细原值不变，
168		// 没有虚构明细，也没有任何承诺被使用或取消。
169		refreshed, err := s.PartStatus(partIsolationPartID, nowOK)
170		if err != nil {
171			t.Fatalf("refreshed part status: %v", err)
172		}
173		assertPartIsoAccount(t, refreshed, 10, 7, 3)
174		if refreshed.PartID != partIsolationPartID {
175			t.Fatalf("refreshed part id = %q, want %q", refreshed.PartID, partIsolationPartID)
176		}
177		if len(refreshed.Details) != 2 {
178			t.Fatalf("refreshed details = %d, want 2", len(refreshed.Details))
179		}
180		assertDetailFact(t, mustDetailByID(t, refreshed.Details, "c-five"), "req-five", 5, 2, 3, CommitmentActive, expFive)
181		assertDetailFact(t, mustDetailByID(t, refreshed.Details, "c-four"), "req-four", 4, 0, 4, CommitmentActive, expFour)
182		if _, ok := detailByID(refreshed, "c-fabricated"); ok {
183			t.Fatalf("refreshed result contains fabricated detail")
184		}
185	
186		// 仓库保存的承诺归属、数量与已用数量不能跟着改变。
187		for _, tc := range []struct {
188			id        string
189			requestID string
190			quantity  int
191			used      int
192			canceled  bool
193			expired   bool
194		}{
195			{"c-five", "req-five", 5, 2, false, false},
196			{"c-four", "req-four", 4, 0, false, false},
197		} {
198			c, err := s.Commitment(tc.id)
199			if err != nil {
200				t.Fatalf("commitment %s: %v", tc.id, err)
201			}
202			if c.RequestID != tc.requestID || c.Quantity != tc.quantity || c.Used != tc.used ||
203				c.Canceled != tc.canceled || c.Expired != tc.expired {
